declare %updating function local:upsert(
  $e  as element(),
  $an as xs:QName,
  $av as xs:anyAtomicType
) {
  let $ea := $e/attribute()[node-name(.) = $an]
  return if (empty($ea))
    then insert node attribute { $an } { $av } into $e
    else replace value of node $ea with $av
};
<a x="1"/> transform with {
  local:upsert(., xs:QName('x'), 2),
  local:upsert(., xs:QName('y'), 3)
}

declare %updating function local:rename(
  $nodes as element()*
) {
  if (exists($nodes)) then (
    rename node head($nodes) as 'x',
    local:rename(tail($nodes))
  ) else ()
};
<a><b/><c/><d/></a> transform with { local:rename(*) }

