declare %updating function local:insert-copy(
  $node as element()
) {
  insert node ($node transform with { rename node . as 'c' }) into $node
};
<a><b/></a> transform with { local:insert-copy(b) }

declare %updating function local:insert(
  $node  as element(),
  $count as xs:integer
) {
  if ($count > 0) then (
    insert node <x/> into $node,
    local:insert($node, $count - 1)
  ) else ()
};
count((<a/> transform with { local:insert(., 500) })/x)

